CREATE DATABASE IF NOT EXISTS kasir_restoran CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE kasir_restoran;
CREATE TABLE IF NOT EXISTS admins (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales (id BIGINT AUTO_INCREMENT PRIMARY KEY, client_key VARCHAR(100) NOT NULL UNIQUE, sale_time DATETIME NOT NULL, order_type VARCHAR(20) NOT NULL DEFAULT 'dine-in', customer_name VARCHAR(120) NOT NULL, subtotal BIGINT NOT NULL, discount BIGINT NOT NULL DEFAULT 0, discount_code VARCHAR(40) DEFAULT '', total BIGINT NOT NULL, items_json LONGTEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(sale_time));
